ALTER TABLE public.chart_of_accounts ADD COLUMN IF NOT EXISTS future_account_id uuid REFERENCES public.chart_of_accounts(id);
CREATE OR REPLACE FUNCTION public.finance_account_merge(t uuid,source uuid,target uuid,d date,reclass boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a chart_of_accounts;b chart_of_accounts;r record;ls jsonb:='[]';q uuid;stamp text;BEGIN IF NOT finance_schedule_manager(t) THEN RAISE EXCEPTION 'Owner or admin required';END IF;PERFORM finance_assert_open(t,d);PERFORM pg_advisory_xact_lock(hashtextextended('account-merge:'||t::text,0));SELECT * INTO a FROM chart_of_accounts WHERE tenant_id=t AND id=source FOR UPDATE;SELECT * INTO b FROM chart_of_accounts WHERE tenant_id=t AND id=target FOR UPDATE;IF a.id IS NULL OR b.id IS NULL OR a.id=b.id OR a.account_type<>b.account_type OR a.normal_side<>b.normal_side OR NOT b.is_active OR b.future_account_id IS NOT NULL OR a.future_account_id IS NOT NULL THEN RAISE EXCEPTION 'Choose distinct unmerged active accounts of the same type and normal side';END IF;IF EXISTS(SELECT 1 FROM chart_of_accounts WHERE tenant_id=t AND future_account_id=source) THEN RAISE EXCEPTION 'An existing redirect points to this account';END IF;
UPDATE chart_of_accounts SET future_account_id=target WHERE tenant_id=t AND id=source;
IF reclass THEN FOR r IN SELECT l.venue,sum(l.debit-l.credit) amount FROM journal_lines l JOIN journal_entries e ON e.id=l.entry_id WHERE l.tenant_id=t AND l.account_id=source AND e.tenant_id=t AND e.status='posted' AND e.entry_date<=d GROUP BY l.venue LOOP IF r.amount<>0 THEN ls:=ls||jsonb_build_array(jsonb_build_object('account_id',target,'debit',greatest(r.amount,0),'credit',greatest(-r.amount,0),'venue',r.venue),jsonb_build_object('account_id',source,'debit',greatest(-r.amount,0),'credit',greatest(r.amount,0),'venue',r.venue));END IF;END LOOP;
IF jsonb_array_length(ls)>0 THEN SELECT md5(coalesce(string_agg(l.id::text||':'||l.debit||':'||l.credit||':'||coalesce(l.venue,''),',' ORDER BY l.id),'')) INTO stamp FROM journal_lines l JOIN journal_entries e ON e.id=l.entry_id WHERE l.tenant_id=t AND l.account_id=source AND e.tenant_id=t AND e.status='posted' AND e.entry_date<=d;q:=finance_schedule_enqueue(t,d,'account_reclass',a.name||' → '||b.name,'Confirmed account merge; historic posted lines remain unchanged','account-reclass:'||source,ls,jsonb_build_object('account_source',source,'account_target',target,'ledger_fingerprint',stamp));END IF;END IF;
INSERT INTO audit_log(tenant_id,user_id,action,entity_type,entity_id,details) VALUES(t,auth.uid(),'account_future_merge','chart_of_accounts',source::text,jsonb_build_object('target',target,'draft',q));RETURN q;END $$;
REVOKE ALL ON FUNCTION public.finance_account_merge(uuid,uuid,uuid,date,boolean) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.finance_account_merge(uuid,uuid,uuid,date,boolean) TO authenticated;
CREATE FUNCTION public.finance_future_account_line() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE dest uuid;BEGIN IF TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM journal_entries WHERE id=OLD.entry_id AND status='posted') THEN RETURN NEW;END IF;IF coalesce(current_setting('finance.keep_reclass_accounts',true),'')='yes' THEN RETURN NEW;END IF;SELECT future_account_id INTO dest FROM chart_of_accounts WHERE id=NEW.account_id AND tenant_id=NEW.tenant_id;IF dest IS NOT NULL THEN NEW.account_id:=dest;END IF;RETURN NEW;END $$;
CREATE TRIGGER future_account_line BEFORE INSERT OR UPDATE OF account_id ON public.journal_lines FOR EACH ROW EXECUTE FUNCTION public.finance_future_account_line();
DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.finance_schedule_approve(uuid,uuid,date)'::regprocedure) INTO def;def:=replace(def,'IF q.kind=''tax'' THEN','IF q.kind=''account_reclass'' THEN IF NOT EXISTS(SELECT 1 FROM chart_of_accounts WHERE tenant_id=t AND id=(q.source_data->>''account_source'')::uuid AND future_account_id=(q.source_data->>''account_target'')::uuid) OR (SELECT md5(coalesce(string_agg(l.id::text||'':''||l.debit||'':''||l.credit||'':''||coalesce(l.venue,''''),'','' ORDER BY l.id),'''')) FROM journal_lines l JOIN journal_entries e ON e.id=l.entry_id WHERE l.tenant_id=t AND l.account_id=(q.source_data->>''account_source'')::uuid AND e.tenant_id=t AND e.status=''posted'' AND e.entry_date<=q.entry_date) IS DISTINCT FROM q.source_data->>''ledger_fingerprint'' THEN RAISE EXCEPTION ''Account balance changed; prepare again'';END IF;PERFORM set_config(''finance.keep_reclass_accounts'',''yes'',true);END IF;IF q.kind=''tax'' THEN');def:=replace(def,'RETURN j;','PERFORM set_config(''finance.keep_reclass_accounts'','''',true);RETURN j;');EXECUTE def;END $$;